$ErrorActionPreference = "Stop"

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Write-Base64Utf8File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Base64
    )

    $parent = Split-Path -Parent $Path

    if ($parent -and -not (Test-Path $parent)) {
        New-Item `
            -ItemType Directory `
            -Path $parent `
            -Force |
            Out-Null
    }

    $bytes = if ($Base64.Length -eq 0) {
        [byte[]]@()
    }
    else {
        [System.Convert]::FromBase64String(
            $Base64
        )
    }

    $absolutePath = [System.IO.Path]::GetFullPath(
        (Join-Path (Get-Location) $Path)
    )

    [System.IO.File]::WriteAllBytes(
        $absolutePath,
        $bytes
    )
}

$requiredPaths = @(
    "backend\app\main.py",
    "backend\app\core\config.py",
    "backend\app\workers\tasks.py",
    "backend\app\services\accounting_exports\service.py",
    "backend\app\api\routes\exports.py",
    "scripts\smoke_test.ps1",
    "supabase\migrations"
)

foreach ($requiredPath in $requiredPaths) {
    if (-not (Test-Path $requiredPath)) {
        throw (
            "Run this installer from the DocuFlow AP project root. " +
            "Missing: $requiredPath"
        )
    }
}

