$patchPath = Join-Path `
    $env:TEMP `
    "docuflow_milestone9a2_patch.py"

[System.IO.File]::WriteAllBytes(
    $patchPath,
    [System.Convert]::FromBase64String(
        $patchBase64
    )
)

try {
    python $patchPath

    if ($LASTEXITCODE -ne 0) {
        throw "Milestone 9A2 repository patching failed."
    }
}
finally {
    if (Test-Path $patchPath) {
        Remove-Item `
            $patchPath `
            -Force
    }
}

Write-Host ""
Write-Host "Milestone 9A2 files installed."
Write-Host "No migration, rebuild, test or commit has been performed."
